function EXTRA(R,ICON){
 /* hook: a weak signal from a far tower, and a strong neighbour on the next channel */
 const phone=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><rect x="-22" y="-40" width="44" height="80" rx="9" fill="#343A40"/><rect x="-16" y="-30" width="32" height="54" rx="4" fill="#D0EBFF"/><circle cx="0" cy="32" r="3" fill="#ADB5BD"/></g>`;
 const arcs=(x,y,n,col,w,op)=>Array.from({length:n},(_,i)=>`<path d="M${x+18+i*16},${y-22-i*8} a${26+i*16},${26+i*16} 0 0 1 0,${44+i*16}" fill="none" stroke="${col}" stroke-width="${w}" stroke-opacity="${op}" stroke-linecap="round"/>`).join('');
 ICON.rfWhisper=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${MW_box(0,0,380,170,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}
  <path d="M40,150 L62,30 L84,150 M48,110 L76,110 M54,72 L70,72 M44,130 L80,90 M80,130 L44,90" fill="none" stroke="${INK}" stroke-width="4" stroke-linejoin="round"/><circle cx="62" cy="26" r="6" fill="${RED}"/>
  ${arcs(62,52,3,BLU,3,.35)}${phone(330,86,.9)}
  ${MW_T(176,62,'far tower',{fs:22,fw:800,a:'middle',fill:INK})}${MW_T(196,104,'a whisper:',{fs:22,fw:700,a:'middle',fill:MW_G})}${MW_T(196,136,'noise sets the floor',{fs:22,fw:700,a:'middle',fill:BLU})}</g>`;
 ICON.rfShout=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${MW_box(0,0,380,170,{fill:'#FFFFFF',st:ORG,sw:3,r:18})}
  ${phone(50,86,.9)}${arcs(50,86,4,ORG,5,.85)}${phone(330,86,.9)}
  ${MW_T(212,62,'next channel',{fs:22,fw:800,a:'middle',fill:INK})}${MW_T(212,104,'a shout:',{fs:22,fw:700,a:'middle',fill:MW_G})}${MW_T(212,136,'IM3 and compression',{fs:22,fw:700,a:'middle',fill:ORG})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.rfRecapQ=(x,y)=>{const X=f=>30+f*96,Y=q=>300-q*30;return `<g transform="translate(${x-210} ${y-165})">${MW_axes(30,300,410,20)}${MW_T(40,30,'Q',{fs:24,fw:800,fill:MW_G})}${MW_T(410,290,'f',{fs:24,fw:800,a:'end',fill:MW_G})}
  ${MW_pl(MW_pts(MW_Qs,0,2.6,X,Y),MW_LG,4,'9 7')}${MW_pl(MW_pts(MW_Qe,0,MW_FSR,X,Y),BLU,6)}
  <circle cx="${X(2)}" cy="${Y(6.283).toFixed(1)}" r="8" fill="${MW_LG}"/>${MW_T(X(2)-14,Y(6.283)-4,'6.28',{fs:26,fw:800,a:'end',fill:MW_G})}
  <circle cx="${X(2)}" cy="${Y(4.2485).toFixed(1)}" r="9" fill="${BLU}"/>${MW_T(X(2),Y(4.2485)+44,'4.25',{fs:30,fw:800,a:'middle',fill:BLU})}
  ${MW_L(X(MW_FSR),300,X(MW_FSR),60,GRN,3,'stroke-dasharray="7 6"')}${MW_T(X(MW_FSR)-8,54,MW_fSR,{fs:26,fw:800,a:'end',fill:GRN})}</g>`};
 ICON.rfRecapNF=(x,y)=>{const W=v=>v*160;return `<g transform="translate(${x-210} ${y-165})">
  ${[['LNA',1.585,BLU],['mixer',0.470,ORG],['IF amp',0.0285,GRN]].map(([t,v,col],i)=>MW_T(20,52+i*84,t,{fs:24,fw:800,fill:col})+MW_R(20,64+i*84,Math.max(W(v),8),40,col)+MW_T(34+Math.max(W(v),8),94+i*84,v,{fs:26,fw:800,fill:col})).join('')}
  ${MW_L(20,300,400,300,INK,3)}${MW_T(20,290,'F = 2.083 = 3.19 dB',{fs:30,fw:800,fill:INK})}</g>`};
 ICON.rfRecapIP=(x,y)=>{const X=p=>40+(p+25)*10,Y=o=>310-(o+60)*3;return `<g transform="translate(${x-210} ${y-165})">${MW_axes(40,310,400,10)}
  ${MW_L(X(-25),Y(-5),X(10),Y(30),BLU,5)}${MW_L(X(-20),Y(-60),X(10),Y(30),GRN,5)}
  <circle cx="${X(10)}" cy="${Y(30)}" r="10" fill="${INK}"/>${MW_T(X(10)-16,Y(30)+8,'IIP3',{fs:28,fw:800,a:'end',fill:INK})}
  ${MW_T(X(-9),Y(14)-14,'slope 1',{fs:24,fw:800,a:'end',fill:BLU})}${MW_T(X(-8)+14,Y(-36)+10,'slope 3',{fs:24,fw:800,fill:GRN})}</g>`};
}
